// === Tab: mySketch.js ===
/*
It is a 2D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Lines".

This time, I'm trying out a watercolour look, which I'm excited
to experiment with!

Interaction:
- Space Bar: Pause/Play
- Mouse Wheel: Forward / Backward in time
- Reload or wait ten seconds for new variation
*/

const scale = Math.max(1, devicePixelRatio / 2)
let theShader, wheelDelta = 0, wheelOffset = 0, pause = false, paused = 0, time = 0, startRandom = Math.random()

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2995416/files/vert.glsl', 'frag.glsl')
}

function setup() {
	pixelDensity(scale)
	createCanvas(windowWidth, windowHeight, WEBGL)
}

function windowResized() {
	pixelDensity(scale)
	resizeCanvas(windowWidth, windowHeight)
}

function mouseWheel(e) {
	if (wheelDelta * e.deltaY < 0) {
		wheelDelta = e.deltaY
	} else {
		wheelDelta = lerp(wheelDelta, e.deltaY, .05)
	}
	wheelOffset += wheelDelta
}

function keyPressed(e) {
	if (e.key === " ") {
		if (!pause) {
			pause = true
		} else {
			pause = false
			paused = millis() - time
		}
	}
}

function draw() {
  shader(theShader)
  if (!pause) time = millis() - paused
  theShader.setUniform("resolution", [width * scale, height * scale])
  theShader.setUniform("wheel", [wheelDelta, wheelOffset])
  theShader.setUniform("startRandom", startRandom)
  theShader.setUniform("time", time / 1000.0)
  rect(0, 0, width, height)
}

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/
precision highp float;
out vec4 O;
uniform float time;
uniform float startRandom;
uniform vec2 resolution;
uniform vec2 wheel;
#define FC gl_FragCoord.xy
#define R resolution
#define T (time+wheel.y/1e3)
#define S smoothstep
#define SE(v,a) S(a+1./MN,a-1./MN,v)
#define MN min(R.x,R.y)
#define hue(a) (.5+.5*sin(3.14*(a)+vec3(seed,1.+seed*.25,2.-seed*.125)))
#define mapto(x,a,b,c,d) ((x-a)/(b-a)*(d-c)+c)
#define seed rnd(floor(T*.1)+vec2(startRandom,-startRandom))
float rnd(vec2 a) {
	vec3 p=fract(a.xyx*.1031);
	p+=dot(p,p.yzx+33.33);
	return fract((p.x+p.y)*p.z);
}
float noise(vec2 p) {
	vec2 i=floor(p), u=S(i,i+1.,p), k=vec2(1,0);
	float
	a=rnd(i),
	b=rnd(i+k),
	c=rnd(i+k.yx),
	d=rnd(i+k.xx);
	return mix(mix(a,b,u.x),mix(c,d,u.x),u.y);
}
float fbm(vec2 p) {
	float t=.0, a=1.; mat2 m=mat2(1.2,-.8,1,1.2)*mapto(seed,.0,1.,.6,.8);
	for (int i=0; i<5; i++) {
		t+=a*noise(p);
		p*=m*2.;
		a/=2.;
	}
	return t;
}
vec3 line1(vec2 uv, float k, out float d) {
	vec3 col=vec3(0);
	uv.x-=sin(uv.y*(3.+seed)-fbm(1.+uv*33.)*.02)*.3;
	d=max(abs(uv.x),abs(uv.y)-.2-.05*fbm(uv.xx*33.));
	d=SE(d,.2-.005*fbm(uv.yx*120.));
	col=mix(col,hue(fbm(uv-vec2(fbm(uv.xx*3.),2))-fbm(uv.xx*40.)*.25+fbm(uv*12.)*.125+.58-.025*k),d);
	col=tanh(col);
	col=sqrt(col);
	return col;
}
vec3 line2(vec2 uv, float k, out float d) {
	vec3 col=vec3(0);
	uv=uv.yx;
	uv.x+=sin(uv.y*(2.33+seed)-fbm(uv*33.)*.02)*.26;
	d=max(abs(uv.x),abs(uv.y)-(.3-1.5*uv.y+min(max(.0,mod(T*2.,20.)),1.5*uv.y))-.05*fbm(11.+uv.xx*34.));
	d=SE(d,.2-.005*fbm(1.+uv.yx*120.));
	col=mix(col,.8*hue(fbm(uv-vec2(fbm(uv.xx*3.),2))-fbm(uv.xx*40.)*.25+fbm(uv*12.+1.)*.125+.45-.02*k),d);
	return col;
}
vec3 signature(vec2 uv, float k, out float d) {
	vec3 col=vec3(0);
	if (R.y>R.x) uv=vec2(-uv.y+.15,-uv.x);
	uv.x=mapto(uv.x,-.5,.5,-.5,.3);
	uv.y=mapto(uv.y,-.6,.6,-.1,.4);
	uv.y+=.02*sin(uv.x*53.-12.3*uv.y-2.2*sin(uv.x*20.-2.)-21.*uv.y-sin(uv.x*20.-2.))
		+(.004*(1.-seed))*cos(uv.x*(114.*(1.-seed))+2.*(1.+seed)-2.*sin(uv.y*12.)+seed)
		-.0025*fbm(3.+uv.yx*120.);
	uv.x-=clamp(uv.x,-.2,-.2+min(mod(T*2.,20.)*.2,.2));
	d=length(uv);
	d=SE(d,3e-3);
	col=mix(col,.8*hue(fbm(uv-vec2(fbm(uv.xx*3.),3))-fbm(uv.xx*40.)*.25+fbm(uv*12.+1.)*.05+.5-.02*k),d);
	col=S(.0,1.,col*col);
	return col;
}
vec3 paper(vec2 uv, float k, out float d) {
	vec3 col=vec3(0);
	uv=vec2(abs(uv.x)-.4-.0025*fbm(uv.yy*2.-22.*fbm(uv.yx*13.37-.42)),abs(uv.y)-.3-.0025*fbm(uv.xx-2.*fbm(uv.yx*22.22)));
	d=max(uv.x,uv.y);
	d=SE(d,.07-.01*fbm(uv));
	col=mix(col,mix(vec3(.95,.92,.9),vec3(.98,.94,.9),k),d);
	return col;
}
vec3 render(vec2 uv) {
	vec2 p=uv;
	float c,d,e,f,h=200.+fbm(p.yx*22.),
	k=sin(p.x*h+p.y*h*2.)-sin(p.x*h-p.y*h*2.);
	vec3 col=vec3(0);
	if (R.y>R.x) uv=-uv.yx;
	col=mix(col,paper(uv,k,c),c);
	uv*=1.8;
	col=mix(col,line1(uv,k,d),d);
	col=mix(col,line2(uv,k,e),e);
	col=mix(col,signature(uv,k,f),f);
	col=mix(col,vec3(dot(col,vec3(.21,.71,.07))),mapto(seed,.0,1.,.0,.2));
	col=mix(vec3(.05,.1,.15)+.1*(sin(p.x*h*10.)+sin(p.y*h*8.)),col,max(c,max(d,max(e,f))));
	return col;
}
void main() {
	vec2 uv=(FC-.5*R)/MN;
	vec3 col=render(uv);
	vec2 c=FC/R;
	c*=1.-c.yx;
	float v=c.x*c.y*25.;
	col=mix(tanh(col*col*col)*.2,col,clamp(pow(v,.08),.0,1.));
	O=vec4(col,1);
}

